/*初始化link相关参数*/
int device_createlink(int nSubInstrmentIndex,long lid)
{
	/*创建发送缓存内存块*/
	auto replyMap = AfxGetContext()->phtVXI11Reply;
	if(replyMap.find(lid) == replyMap.end())
	{
		std::shared_ptr<CY_VXI11_COMMAND_REPLY_CONTEXT> preplyContext = std::make_shared<CY_VXI11_COMMAND_REPLY_CONTEXT>();
		if(preplyContext == NULL)
		{
			VLE_LOGE(CONTROL_LEVEL_ERROR,"CY_VXI11_EC_SRVFUNCREPLYMEMORYERROR[%d]",CY_VXI11_EC_SRVFUNCREPLYMEMORYERROR);
			return CY_VXI11_EC_SRVFUNCREPLYMEMORYERROR;
		}
		preplyContext->pszCommand.reset(new char[MAX_SUPPORTED_VXI11_COMMANDCACHE_LENGTH+MAX_SUPPORTED_VXI11_PER_COMMAND_LENGTH], std::default_delete<char[]>());
		if(preplyContext->pszCommand == NULL)
		{
			VLE_LOGE(CONTROL_LEVEL_ERROR,"CY_VXI11_EC_SRVFUNCCOMMANDCONTEXTMEMORYERROR[%d]",CY_VXI11_EC_SRVFUNCCOMMANDCONTEXTMEMORYERROR);
			return CY_VXI11_EC_SRVFUNCCOMMANDCONTEXTMEMORYERROR;
		}

		preplyContext->nSubInstruId	  = nSubInstrmentIndex;
		preplyContext->lid			  = lid;
		preplyContext->nszCommandHead = 0;
		preplyContext->nszCommandTail = 0;
		preplyContext->nszCommandMaxLength = MAX_SUPPORTED_VXI11_COMMANDCACHE_LENGTH;

		preplyContext->pszReply.reset(new char[MAX_SUPPORTED_VXI11_REPLYCACHE_LENGTH+MAX_SUPPORTED_VXI11_PER_REPLY_LENGTH], std::default_delete<char[]>());
		if(preplyContext->pszReply == NULL)
		{
			VLE_LOGE(CONTROL_LEVEL_ERROR,"CY_VXI11_EC_SRVFUNCREPLYCONTEXTMEMORYERROR[%d]",CY_VXI11_EC_SRVFUNCREPLYCONTEXTMEMORYERROR);
			return CY_VXI11_EC_SRVFUNCREPLYCONTEXTMEMORYERROR;
		}
		preplyContext->nszReplyHead = 0;
		preplyContext->nszReplyTail = 0;
		preplyContext->nszReplyMaxLength = MAX_SUPPORTED_VXI11_COMMANDCACHE_LENGTH;
		replyMap[lid] = preplyContext;
		
		//AfxGetContext()->subInstruManager.CreateSubInstrumentContext(nSubInstrmentIndex,(void*)preplyContext);
		
		VLE_LOGE(CONTROL_LEVEL_DEBUG,"device_write_commandcache create lid,%ld",lid);
	}
	return 0;
}

