/*保存命令到对应缓存队列中*/
int device_write_commandcache(long lid,char* pszData,int nDataLength)
{
	int i;
	char szT[MAX_SUPPORTED_VXI11_PER_COMMAND_LENGTH];
	int nHead,nTail,nStart,nSeg;
	
	auto &replyMap = AfxGetContext()->phtVXI11Reply;
	assert(replyMap.find(lid) != replyMap.end());
	std::shared_ptr<CY_VXI11_COMMAND_REPLY_CONTEXT> preplyContext = replyMap[lid];

	/*拷贝数据到缓冲区尾部*/
	memcpy(preplyContext->pszCommand.get()+preplyContext->nszCommandTail,pszData,nDataLength);
	preplyContext->nszCommandTail = (preplyContext->nszCommandTail + nDataLength);
	if(preplyContext->nszCommandTail > MAX_TCPTRANS_RECV_LENGTH)
	{
		memcpy(preplyContext->pszCommand.get(),preplyContext->pszCommand.get()+preplyContext->nszCommandMaxLength,
			preplyContext->nszCommandTail-preplyContext->nszCommandMaxLength);
			preplyContext->nszCommandTail = preplyContext->nszCommandTail-preplyContext->nszCommandMaxLength;
	}

	/*检测完整指令*/
	nHead = preplyContext->nszCommandHead;
	nTail = preplyContext->nszCommandTail;
	nSeg = preplyContext->nszCommandMaxLength-1;
	nStart = nHead;
	if(nTail < nHead)
	{
		nTail += preplyContext->nszCommandMaxLength;
	}
	
	for(i = nHead;i < nTail;i ++)
	{
		if(preplyContext->pszCommand.get()[i%preplyContext->nszCommandMaxLength] == '\n')
		{
			/*segment*/
			if((i > nSeg) && (nStart < nSeg))
			{
				memcpy(szT,preplyContext->pszCommand.get()+nStart,nSeg-nStart);
				memcpy(szT+nSeg-nStart,preplyContext->pszCommand.get(),i-nSeg);
				AfxGetContext()->pMultiLink->PostScpiCommand(MLINK_SCPISOURCE_TYPE_VXI,preplyContext.get(),szT,i-nStart+1);// 长度加1，保证'\n'符号被保存
			}
			else
			{
				AfxGetContext()->pMultiLink->PostScpiCommand(MLINK_SCPISOURCE_TYPE_VXI,preplyContext.get(),preplyContext->pszCommand.get()+nStart,i-nStart+1);// 长度加1，保证'\n'符号被保存
			}
			nStart = i+1;
		}
	}
	preplyContext->nszCommandHead = nStart%preplyContext->nszCommandMaxLength;
	return 0;
}

/*发送回复数据到发送缓冲区*/
#define RESET_HEAD_TAIL_4_LOOPBACK 1

int device_send_reply(void* pvClientContext,const char* pszData,int nDataLength)
{
	CY_VXI11_COMMAND_REPLY_CONTEXT* preplyContext = (CY_VXI11_COMMAND_REPLY_CONTEXT*)pvClientContext;

	/*注意：检测首尾是否相碰撞*/
	if((preplyContext->nszReplyTail<preplyContext->nszReplyHead) &&
		((preplyContext->nszReplyTail+nDataLength)>preplyContext->nszReplyHead))
	{
		VLE_LOGE(CONTROL_LEVEL_ERROR,"CY_VXI11_EC_SRVFUNCSENDBUFFERHEADTAILERROR[%d]:Tail:%d,Head:%d,Length:%d",
			CY_VXI11_EC_SRVFUNCSENDBUFFERHEADTAILERROR,preplyContext->nszReplyTail,preplyContext->nszReplyHead,nDataLength);
		return CY_VXI11_EC_SRVFUNCSENDBUFFERHEADTAILERROR;
	}
	/*拷贝数据到环形缓冲区*/
	if((preplyContext->nszReplyTail + nDataLength) > preplyContext->nszReplyMaxLength)
	{
#if RESET_HEAD_TAIL_4_LOOPBACK
		preplyContext->nszReplyTail = 0;
        preplyContext->nszReplyHead = 0;
        
        printf("line %d nszReplyTail %d\n",__LINE__,preplyContext->nszReplyTail);
        printf("line %d MAX %d nDataLength %d,offset %d\n",__LINE__,preplyContext->nszReplyMaxLength,nDataLength,preplyContext->nszReplyMaxLength - preplyContext->nszReplyTail);
		memcpy(preplyContext->pszReply.get()+preplyContext->nszReplyTail,pszData,nDataLength);
		preplyContext->nszReplyTail += nDataLength;
#else
        printf("line %d nszReplyTail %d\n",__LINE__,preplyContext->nszReplyTail);
        printf("line %d MAX %d nDataLength %d,offset %d\n",__LINE__,preplyContext->nszReplyMaxLength,nDataLength,preplyContext->nszReplyMaxLength - preplyContext->nszReplyTail);
		memcpy(preplyContext->pszReply.get()+preplyContext->nszReplyTail,pszData,preplyContext->nszReplyMaxLength-preplyContext->nszReplyTail);
		memcpy(preplyContext->pszReply.get(),pszData+preplyContext->nszReplyMaxLength-preplyContext->nszReplyTail,
			preplyContext->nszReplyTail + nDataLength-preplyContext->nszReplyMaxLength);
		preplyContext->nszReplyTail = preplyContext->nszReplyTail + nDataLength-preplyContext->nszReplyMaxLength;
#endif
	}
	else
	{
		memcpy(preplyContext->pszReply.get()+preplyContext->nszReplyTail,pszData,nDataLength);
		preplyContext->nszReplyTail += nDataLength;
	}
	return 0;
}

/*读缓冲区读取回复数据流*/
int device_read_reply(long lid,long requestSize,Device_ReadResp* pResult)
{

	auto &replyMap = AfxGetContext()->phtVXI11Reply;
	assert(replyMap.find(lid) != replyMap.end());
	std::shared_ptr<CY_VXI11_COMMAND_REPLY_CONTEXT> preplyContext = replyMap[lid];
	
	
	if(preplyContext->nszReplyHead == preplyContext->nszReplyTail)
	{
#ifdef DEBUG_SCPI_FUNC_TRACE	
		VLE_LOGE(CONTROL_LEVEL_ERROR,"CY_VXI11_EC_SRVFUNCREPLYREADEHASHERROR-1[%d]",CY_VXI11_EC_SRVFUNCREPLYREADEHASHERROR);
#endif
		return -1;
	}
	
	/*移动缓冲区，保证其线性*/
	if(preplyContext->nszReplyHead > preplyContext->nszReplyTail)
	{
		if((preplyContext->nszReplyTail+preplyContext->nszReplyMaxLength-preplyContext->nszReplyHead) > MAX_SUPPORTED_VXI11_PER_REPLY_LENGTH)
		{
			pResult->error = 10;
			VLE_LOGE(CONTROL_LEVEL_ERROR,"CY_VXI11_EC_SRVFUNCREPLYMOVEREADOUTOFRANGEERROR[%d]:move replycache out of range error,%d",
				CY_VXI11_EC_SRVFUNCREPLYMOVEREADOUTOFRANGEERROR,preplyContext->nszReplyTail+preplyContext->nszReplyMaxLength-preplyContext->nszReplyHead);
			return CY_VXI11_EC_SRVFUNCREPLYMOVEREADOUTOFRANGEERROR;
		}
		memcpy(preplyContext->pszReply.get()+preplyContext->nszReplyMaxLength,preplyContext->pszReply.get(),
			preplyContext->nszReplyTail+preplyContext->nszReplyMaxLength-preplyContext->nszReplyHead);
	}

	/*判断是否分段*/
	if((preplyContext->nszReplyTail-preplyContext->nszReplyHead) < requestSize)
	{
		pResult->reason = 0x04;
		pResult->data.data_len = preplyContext->nszReplyTail-preplyContext->nszReplyHead;
        //printf("LINE %d nszReplyTail %d,nszReplyHead %d requestSize %ld pResult->data.data_len = %d\n"
        //    ,__LINE__,preplyContext->nszReplyTail,preplyContext->nszReplyHead,requestSize,pResult->data.data_len);
#if RESET_HEAD_TAIL_4_LOOPBACK
#else
        if(preplyContext->nszReplyTail < preplyContext->nszReplyHead)//loop back
        {
        	pResult->data.data_len = preplyContext->nszReplyTail + preplyContext->nszReplyMaxLength - preplyContext->nszReplyHead;
        	printf("LINE %d nszReplyTail %d,nszReplyHead %d requestSize %ld pResult->data.data_len = %d\n"
            	,__LINE__,preplyContext->nszReplyTail,preplyContext->nszReplyHead,requestSize,pResult->data.data_len);
        }
#endif
	}
	else
	{
		pResult->reason = 0x01;
		pResult->data.data_len = requestSize-preplyContext->nszReplyHead;
        printf("LINE %d nszReplyTail %d,nszReplyHead %d requestSize %ld pResult->data.data_len = %d\n"
            ,__LINE__,preplyContext->nszReplyTail,preplyContext->nszReplyHead,requestSize,pResult->data.data_len);
	}
	pResult->error = 0;
	pResult->data.data_val = preplyContext->pszReply.get()+preplyContext->nszReplyHead;
	preplyContext->nszReplyHead = (preplyContext->nszReplyHead+pResult->data.data_len)%preplyContext->nszReplyMaxLength;
#ifdef INVALID_INFO	
	VLE_LOGE(CONTROL_LEVEL_DEBUG,"result.error:%ld,result.data.val:%s,result.data.length:%u",
			pResult->error,pResult->data.data_val,pResult->data.data_len);	
#endif
	return 0;
}

